package com.example.demo.agents;

import com.example.demo.agent.FileAgent;
import com.example.demo.llm.*;

/**
 * Builder agent: writes files based on the code generated by the Coder agent.
 * Extends FileAgent to have file system capabilities.
 */
public class BuilderAgent extends FileAgent {

    private static final String SYSTEM_MESSAGE = """
            You are a Builder agent in a multi-agent system.
            Your role is to write the actual files based on the code provided by the Coder agent.
            
            Rules:
            1. Parse the code blocks from the Coder's output
            2. Write each file to the specified path
            3. Create directories as needed
            4. Report any errors during file writing
            5. Output a summary of all files created
            """;

    /**
     * Create a new BuilderAgent.
     */
    public BuilderAgent(LlmClient llmClient, LlmConfig config) {
        super("builder", SYSTEM_MESSAGE, llmClient, config);
    }
}
